(1060772, 127860, 14614, '<td valign="top">frame''s just a bit off level -- otherwise a clever idea</td>', 'frame''s just a bit off level -- otherwise a clever idea', '2004-12-13 20:31:04.000000', NULL, 1),
(1060774, 127664, 29477, '<td valign="top">Great composition and depth...Definitely a top contender.  Wonderful picture.</td>', 'Great composition and depth...Definitely a top contender.  Wonderful picture.', '2004-12-13 20:31:48.000000', NULL, 1),
