(1060778, 127813, 29477, '<td valign="top">Great perspective and image...Nice variation from inside looking out and framing of the other broken down vehicles.  Well done...8</td>', 'Great perspective and image...Nice variation from inside looking out and framing of the other broken down vehicles.  Well done...8', '2004-12-13 20:34:00.000000', NULL, 1),
