(1060919, 127948, 18870, '<td valign="top">OH MY GOD!  I saw that picture and instantly thought of it being my Rebel and the thought totally freaked me out.  Good job...you earned a ten from me!!!</td>', 'OH MY GOD!  I saw that picture and instantly thought of it being my Rebel and the thought totally freaked me out.  Good job...you earned a ten from me!!!', '2004-12-13 21:55:25.000000', NULL, 1),
(1060941, 127633, 28003, '<td valign="top">Nice, fairly unique idea. Perhaps the rose could use a little more light to make it stand out from the background more... I like the way that the break isn''t visible, but is implied.</td>', 'Nice, fairly unique idea. Perhaps the rose could use a little more light to make it stand out from the background more... I like the way that the break isn''t visible, but is implied.', '2004-12-13 22:20:36.000000', NULL, 1),
(1060944, 128012, 18194, '<td valign="top">I find the background fairly distracting in this photo.  Perhaps if the photo was taken from a different vantage point to avoid the busy background?</td>', 'I find the background fairly distracting in this photo.  Perhaps if the photo was taken from a different vantage point to avoid the busy background?', '2004-12-13 22:21:26.000000', NULL, 1),
(1060949, 127373, 28003, '<td valign="top">Perhaps cropping more tightly (particularly losing the space at the top or bottom) might make this more interesting.</td>', 'Perhaps cropping more tightly (particularly losing the space at the top or bottom) might make this more interesting.', '2004-12-13 22:23:20.000000', NULL, 1),
(1060951, 126372, 18194, '<td valign="top">I may be missing something here but I dont see anything in the photo that would lead me to believe that it is broken.<br/>I like the background and the colors.</td>', 'I may be missing something here but I dont see anything in the photo that would lead me to believe that it is broken.I like the background and the colors.', '2004-12-13 22:23:51.000000', NULL, 1),
(1060952, 127255, 28003, '<td valign="top">Perhaps some more dramatic (less flat) lighting would make this a little more interesting. Also possibly a plainer (or more blurred) background.</td>', 'Perhaps some more dramatic (less flat) lighting would make this a little more interesting. Also possibly a plainer (or more blurred) background.', '2004-12-13 22:24:16.000000', NULL, 1),
