(1061418, 127885, 29535, '<td valign="top">Without the title this would not represent broken at all, sorry.  Great composition and sky though.</td>', 'Without the title this would not represent broken at all, sorry.  Great composition and sky though.', '2004-12-14 05:37:21.000000', NULL, 1),
(1061419, 127474, 29535, '<td valign="top">You bastard!  Do you know how many African kids want cameras??<br/> <br/>Great shot though.</td>', 'You bastard!  Do you know how many African kids want cameras?? Great shot though.', '2004-12-14 05:38:04.000000', NULL, 1),
(1061420, 127514, 29535, '<td valign="top">I don''t see how the fuji CDR, pshop and the calendar relate.  It also seems a little dark and has a snapshot qulity to it, the background is distracting.</td>', 'I don''t see how the fuji CDR, pshop and the calendar relate.  It also seems a little dark and has a snapshot qulity to it, the background is distracting.', '2004-12-14 05:38:56.000000', NULL, 1),
(1061421, 127900, 29535, '<td valign="top">Creepy as hell, I like it!  Shouldn''t have cropped out the feet though.  Great colours and lighting.</td>', 'Creepy as hell, I like it!  Shouldn''t have cropped out the feet though.  Great colours and lighting.', '2004-12-14 05:39:34.000000', NULL, 1),
(1061422, 126724, 29535, '<td valign="top">A little confused as to whats being shown, good title and nice shades.</td>', 'A little confused as to whats being shown, good title and nice shades.', '2004-12-14 05:39:55.000000', NULL, 1),
(1061423, 127560, 29535, '<td valign="top">Always with the fortune cookie shots :p  Not bad, broken being written has no relevance though, as the cookie is clearly the broken thing...</td>', 'Always with the fortune cookie shots :p  Not bad, broken being written has no relevance though, as the cookie is clearly the broken thing...', '2004-12-14 05:40:42.000000', NULL, 1),
(1061424, 127604, 29535, '<td valign="top">I don''t like the line in the middle where the two shades of white clash, but good idea.  Ok composition.</td>', 'I don''t like the line in the middle where the two shades of white clash, but good idea.  Ok composition.', '2004-12-14 05:41:10.000000', NULL, 1),
(1061425, 127437, 29535, '<td valign="top">Why does everyone have so many computers to destroy???  Ok shoit, not sure about all the yellow on the left.</td>', 'Why does everyone have so many computers to destroy???  Ok shoit, not sure about all the yellow on the left.', '2004-12-14 05:41:53.000000', NULL, 1),
(1061426, 126390, 29535, '<td valign="top">Good idea, grat composition and nice B&amp;W, well done.</td>', 'Good idea, grat composition and nice B&W, well done.', '2004-12-14 05:42:17.000000', NULL, 1),
(1061427, 127679, 29535, '<td valign="top">Ok I guess,not very original.</td>', 'Ok I guess,not very original.', '2004-12-14 05:42:33.000000', NULL, 1),
(1061428, 127890, 29535, '<td valign="top">Strange title, nice setup and lighting though, quite funny.</td>', 'Strange title, nice setup and lighting though, quite funny.', '2004-12-14 05:42:54.000000', NULL, 1),
(1061429, 127610, 29535, '<td valign="top">Nice shot, foreground is a little distracting and it''s hard to see whats broken, but good.</td>', 'Nice shot, foreground is a little distracting and it''s hard to see whats broken, but good.', '2004-12-14 05:43:20.000000', NULL, 1),
(1061431, 127973, 29535, '<td valign="top">Would have been nicer to have some glass remain in the face of the clock, luck of the draw I guess.</td>', 'Would have been nicer to have some glass remain in the face of the clock, luck of the draw I guess.', '2004-12-14 05:43:59.000000', NULL, 1),
(1061432, 127835, 29535, '<td valign="top">I''m so glad I didn''t do broken home now, I thought it would be origjnal too :(  This however is a great, orignal take on it, well done.  Great DOF and focus, good idea and subject.</td>', 'I''m so glad I didn''t do broken home now, I thought it would be origjnal too :(  This however is a great, orignal take on it, well done.  Great DOF and focus, good idea and subject.', '2004-12-14 05:44:57.000000', NULL, 1),
(1061434, 126600, 29535, '<td valign="top">The stick is out of focus on the right, and is firther forward drawing the eye much better than the focused part on the floor.  Composition is lacking colours are good.</td>', 'The stick is out of focus on the right, and is firther forward drawing the eye much better than the focused part on the floor.  Composition is lacking colours are good.', '2004-12-14 05:45:35.000000', NULL, 1),
(1061435, 127850, 29535, '<td valign="top">A little bland, window shots never do it for me.</td>', 'A little bland, window shots never do it for me.', '2004-12-14 05:45:55.000000', NULL, 1),
(1061436, 127664, 29535, '<td valign="top">Excellent, althoug I actually think the person detracts from the photograph.</td>', 'Excellent, althoug I actually think the person detracts from the photograph.', '2004-12-14 05:46:17.000000', NULL, 1),
(1061437, 127475, 29535, '<td valign="top">Good idea, the lighting needs a little work op in the northwest, but nice idea, focus and composition.</td>', 'Good idea, the lighting needs a little work op in the northwest, but nice idea, focus and composition.', '2004-12-14 05:46:53.000000', NULL, 1),
(1061438, 127871, 29535, '<td valign="top">That''s a really cool effect, and the black background makes this photo even better.  Well done.</td>', 'That''s a really cool effect, and the black background makes this photo even better.  Well done.', '2004-12-14 05:47:17.000000', NULL, 1),
