(1061440, 127811, 29535, '<td valign="top">Too many lightbulbs!  But good shot.</td>', 'Too many lightbulbs!  But good shot.', '2004-12-14 05:47:46.000000', NULL, 1),
(1061441, 126711, 29535, '<td valign="top">It''s a little out of focus, and the background is too infocus, reduce your aperture and sort your focus out.  Also, I can''t find a link to the challenge.</td>', 'It''s a little out of focus, and the background is too infocus, reduce your aperture and sort your focus out.  Also, I can''t find a link to the challenge.', '2004-12-14 05:48:35.000000', NULL, 1),
