(1061811, 126647, 29535, '<td valign="top">Nice idea, The sepia tone is excellent.  Not a fan of the angle for some reason though, and the lighting isn''t quite perfect.</td>', 'Nice idea, The sepia tone is excellent.  Not a fan of the angle for some reason though, and the lighting isn''t quite perfect.', '2004-12-14 12:07:58.000000', NULL, 1),
(1061813, 127599, 29535, '<td valign="top">Nice focus and composition.</td>', 'Nice focus and composition.', '2004-12-14 12:08:16.000000', NULL, 1),
(1061814, 127600, 29535, '<td valign="top">I can''t believe you did this!  Why must people keep breaking things :(  Nice shot, excellent background/idea/focus/originality, hell, this is a high rated photograph from me.</td>', 'I can''t believe you did this!  Why must people keep breaking things :(  Nice shot, excellent background/idea/focus/originality, hell, this is a high rated photograph from me.', '2004-12-14 12:09:02.000000', NULL, 1),
(1061815, 127570, 29535, '<td valign="top">I love this shot, finally a decent example of how to use selective desat, fantastic colouring, great angle and subject.  Well done.</td>', 'I love this shot, finally a decent example of how to use selective desat, fantastic colouring, great angle and subject.  Well done.', '2004-12-14 12:09:41.000000', NULL, 1),
(1061819, 127816, 29535, '<td valign="top">Nice border, fantastic background and great conversion to B&amp;W.  The subject is good and well spotted, brilliant composition.  Bumping this up once again.</td>', 'Nice border, fantastic background and great conversion to B&W.  The subject is good and well spotted, brilliant composition.  Bumping this up once again.', '2004-12-14 12:10:35.000000', NULL, 1),
(1061822, 127978, 29535, '<td valign="top">The best light bulb picture, fantastic shot which must have been difficult to capture.  Congrats.</td>', 'The best light bulb picture, fantastic shot which must have been difficult to capture.  Congrats.', '2004-12-14 12:11:05.000000', NULL, 1),
(1061823, 127504, 29535, '<td valign="top">Fantastic pin sharp focus, nice idea and good lighting.</td>', 'Fantastic pin sharp focus, nice idea and good lighting.', '2004-12-14 12:11:41.000000', NULL, 1),
(1061824, 127601, 29535, '<td valign="top">Lots of light bulb pics, but this is one of the better onces, great colours and composition.</td>', 'Lots of light bulb pics, but this is one of the better onces, great colours and composition.', '2004-12-14 12:12:07.000000', NULL, 1),
(1061829, 127521, 29535, '<td valign="top">I hope you aren''t white and living in Iraq man, it''s kinda unsafe dontcha know :(<br/> <br/>Anyways, great photo, was this actually their home?  Fantastic shot... bloody wars... grr.  Brilliant shot anyway.</td>', 'I hope you aren''t white and living in Iraq man, it''s kinda unsafe dontcha know :( Anyways, great photo, was this actually their home?  Fantastic shot... bloody wars... grr.  Brilliant shot anyway.', '2004-12-14 12:13:37.000000', NULL, 1),
(1061831, 127351, 29535, '<td valign="top">Cute!  Great shot, lighting, composition, everythng is great.</td>', 'Cute!  Great shot, lighting, composition, everythng is great.', '2004-12-14 12:13:55.000000', NULL, 1),
(1061832, 127927, 29535, '<td valign="top">Very original, great shot DOF and lighting.  Love it!</td>', 'Very original, great shot DOF and lighting.  Love it!', '2004-12-14 12:14:21.000000', NULL, 1),
(1061836, 126334, 29535, '<td valign="top">Ouch, how''d you do the blood?  Great composition and idea.</td>', 'Ouch, how''d you do the blood?  Great composition and idea.', '2004-12-14 12:15:45.000000', NULL, 1),
(1061838, 127863, 29535, '<td valign="top">Simple, and brilliant technical shot.  Well done!</td>', 'Simple, and brilliant technical shot.  Well done!', '2004-12-14 12:16:08.000000', NULL, 1),
