(1061859, 127987, 23294, '<td valign="top">really cool coloring.  A border that actually works!  The subject is I guess a net or something?  it has a lot of appeal but I think it''s mostly the nice colors.  Overall one of my favorites.  7.</td>', 'really cool coloring.  A border that actually works!  The subject is I guess a net or something?  it has a lot of appeal but I think it''s mostly the nice colors.  Overall one of my favorites.  7.', '2004-12-14 12:21:09.000000', NULL, 1),
(1061860, 126448, 23294, '<td valign="top">Brilliant!  A very clever idea indeed, and well executed.  one of my top 2 pics. 8.</td>', 'Brilliant!  A very clever idea indeed, and well executed.  one of my top 2 pics. 8.', '2004-12-14 12:21:48.000000', NULL, 1),
(1061929, 127357, 24925, '<td valign="top">A little too much work on the sky here, I think...Good placement and silhouette, though.  With a sky that didn''t look like mold (in a literal sense), this would have received an 8 or 9...As is, it gets a 6.</td>', 'A little too much work on the sky here, I think...Good placement and silhouette, though.  With a sky that didn''t look like mold (in a literal sense), this would have received an 8 or 9...As is, it gets a 6.', '2004-12-14 13:03:59.000000', NULL, 1),
(1061968, 127357, 27524, '<td valign="top">Real dramatic shot... well done.</td>', 'Real dramatic shot... well done.', '2004-12-14 13:44:54.000000', NULL, 1),
