(1062195, 127862, 20779, '<td valign="top">Very striking image and perfectly executed.</td>', 'Very striking image and perfectly executed.', '2004-12-14 17:14:22.000000', NULL, 1),
(1062196, 127065, 20779, '<td valign="top">This could very well ribbon IMO. Ingenius find or set-up, outstanding processing, perfect composition, extremely creative in approach in all ways.</td>', 'This could very well ribbon IMO. Ingenius find or set-up, outstanding processing, perfect composition, extremely creative in approach in all ways.', '2004-12-14 17:15:50.000000', NULL, 1),
(1062198, 126979, 20779, '<td valign="top">This is the only image depicting heartbreak that really worked for me in the challenge. Extremely well done. The woman appears completely lost to us, and the tones and grain all contribute to sustaining that feel throughout the image.</td>', 'This is the only image depicting heartbreak that really worked for me in the challenge. Extremely well done. The woman appears completely lost to us, and the tones and grain all contribute to sustaining that feel throughout the image.', '2004-12-14 17:17:34.000000', NULL, 1),
(1062200, 127484, 20779, '<td valign="top">This photograph really shook me. Very powerful image and extremely insightful work.</td>', 'This photograph really shook me. Very powerful image and extremely insightful work.', '2004-12-14 17:18:49.000000', NULL, 1),
(1062202, 128003, 20779, '<td valign="top">Extremely good insight into creating a subjective feel of brokeness. Captivating photograph rendered perfectly for the challenge.</td>', 'Extremely good insight into creating a subjective feel of brokeness. Captivating photograph rendered perfectly for the challenge.', '2004-12-14 17:20:11.000000', NULL, 1),
(1062203, 127442, 17033, '<td valign="top">Clever image but I think it''s not as it appears. Having a book filled with these photos at home I''m sure the egg would shatter and explode outwards much more violently. The round is also captured with much too much clarity and the outside setting is a giveaway - these shots require sensors and very precise strobe firing...only indoors conditions will do. Picture looks great though!</td>', 'Clever image but I think it''s not as it appears. Having a book filled with these photos at home I''m sure the egg would shatter and explode outwards much more violently. The round is also captured with much too much clarity and the outside setting is a giveaway - these shots require sensors and very precise strobe firing...only indoors conditions will do. Picture looks great though!', '2004-12-14 17:20:27.000000', NULL, 1),
(1062204, 126721, 20779, '<td valign="top">The lighting and colors captured are just superb and make this an outstanding piece of work. I personally think you did an excellent job in your choice of border also.</td>', 'The lighting and colors captured are just superb and make this an outstanding piece of work. I personally think you did an excellent job in your choice of border also.', '2004-12-14 17:21:16.000000', NULL, 1),
