(1062785, 126448, 22479, '<td valign="top">Outstanding entry on all aspects, theme, artistic, and technical. Wonderful DOF, focus, and detail. The composition, framing, and tone is very effective. My pick for top 10. 8</td>', 'Outstanding entry on all aspects, theme, artistic, and technical. Wonderful DOF, focus, and detail. The composition, framing, and tone is very effective. My pick for top 10. 8', '2004-12-14 23:33:55.000000', NULL, 1),
(1062820, 127648, 28003, '<td valign="top">Interesting lighting - nice work. I think the wine stains should either be removed entirely or made much more pronounced.</td>', 'Interesting lighting - nice work. I think the wine stains should either be removed entirely or made much more pronounced.', '2004-12-14 23:48:18.000000', NULL, 1),
(1062824, 127758, 28003, '<td valign="top">It''s not really obvious whether the HD is broken or not. If in fact it''s not broken, then I don''t get the connection to the challenge at all. Shame, because otherwise it''s a decent shot.</td>', 'It''s not really obvious whether the HD is broken or not. If in fact it''s not broken, then I don''t get the connection to the challenge at all. Shame, because otherwise it''s a decent shot.', '2004-12-14 23:50:10.000000', NULL, 1),
(1062825, 126699, 28003, '<td valign="top">I guess I just don''t get it. Sorry.<br/></td>', 'I guess I just don''t get it. Sorry.', '2004-12-14 23:51:02.000000', NULL, 1),
(1062830, 127994, 28003, '<td valign="top">Cute, well staged.</td>', 'Cute, well staged.', '2004-12-14 23:52:53.000000', NULL, 1),
(1062831, 126647, 28003, '<td valign="top">Interesting play on the challenge, and very nice shot.</td>', 'Interesting play on the challenge, and very nice shot.', '2004-12-14 23:53:15.000000', NULL, 1),
(1062836, 127915, 28003, '<td valign="top">A good idea, but a fairly average implementation.</td>', 'A good idea, but a fairly average implementation.', '2004-12-14 23:54:01.000000', NULL, 1),
