INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1064245, 126647, 8970, '<td valign="top">Too much detail is lost in the black areas</td>', 'Too much detail is lost in the black areas', '2004-12-15 13:57:14.000000', NULL, 1),
(1064287, 127554, 28003, '<td valign="top">Interesting lighting and use of negative space.</td>', 'Interesting lighting and use of negative space.', '2004-12-15 14:14:40.000000', NULL, 1),
(1064289, 127610, 28003, '<td valign="top">Nice sky, decent composition.</td>', 'Nice sky, decent composition.', '2004-12-15 14:15:55.000000', NULL, 1),
(1064294, 126721, 28003, '<td valign="top">Good lighting, and nice contrasts. I''m not sure about the composition though - why crop the right-most nut while leaving all the space on the left?</td>', 'Good lighting, and nice contrasts. I''m not sure about the composition though - why crop the right-most nut while leaving all the space on the left?', '2004-12-15 14:17:29.000000', NULL, 1),
(1064317, 127660, 28003, '<td valign="top">Nice shot. The fact that it''s loaded up with stuff detracts from the impression that it might be broken, however.</td>', 'Nice shot. The fact that it''s loaded up with stuff detracts from the impression that it might be broken, however.', '2004-12-15 14:28:57.000000', NULL, 1),
(1064319, 127832, 28003, '<td valign="top">Interesting take, but the picture is a little soft.</td>', 'Interesting take, but the picture is a little soft.', '2004-12-15 14:29:41.000000', NULL, 1),
(1064320, 127627, 28003, '<td valign="top">Nice textures.</td>', 'Nice textures.', '2004-12-15 14:30:11.000000', NULL, 1),
(1064321, 127475, 28003, '<td valign="top">A bit gimmicky, but cute.</td>', 'A bit gimmicky, but cute.', '2004-12-15 14:30:46.000000', NULL, 1),
(1064324, 127990, 28003, '<td valign="top">Inventive shot, well lit and composed.</td>', 'Inventive shot, well lit and composed.', '2004-12-15 14:32:21.000000', NULL, 1),
(1064327, 127442, 28003, '<td valign="top">Nice shot, would have preferred some more delicate lighting on the egg - the overexposure is a shame. Perhaps a little more motion blur on the bullet? (I''m assuming it''s hanging from a string or something, so I appreciate that motion blur might be tricky!).</td>', 'Nice shot, would have preferred some more delicate lighting on the egg - the overexposure is a shame. Perhaps a little more motion blur on the bullet? (I''m assuming it''s hanging from a string or something, so I appreciate that motion blur might be tricky!).', '2004-12-15 14:33:42.000000', NULL, 1),
(1064330, 127904, 28003, '<td valign="top">Pains? Panes? Ow. Interesting variation between the individual panes.</td>', 'Pains? Panes? Ow. Interesting variation between the individual panes.', '2004-12-15 14:34:17.000000', NULL, 1),
(1064331, 127997, 28003, '<td valign="top">Funny how a lot of people have the same idea... Well lit and composed.</td>', 'Funny how a lot of people have the same idea... Well lit and composed.', '2004-12-15 14:34:39.000000', NULL, 1),
(1064446, 127646, 29269, '<td valign="top">Great timing, a bit weak on lighting. It''s the dark background that dulls the whole image a bit too much for my taste.</td>', 'Great timing, a bit weak on lighting. It''s the dark background that dulls the whole image a bit too much for my taste.', '2004-12-15 15:36:37.000000', NULL, 1),
(1064449, 127474, 8970, '<td valign="top">such a waste of a camera</td>', 'such a waste of a camera', '2004-12-15 15:39:01.000000', NULL, 1),
(1064461, 127848, 7889, '<td valign="top">This is my fav, I love the lighting and the simplicity of the shot. Best of luck<br/></td>', 'This is my fav, I love the lighting and the simplicity of the shot. Best of luck', '2004-12-15 15:43:17.000000', NULL, 1),
(1064463, 126448, 28962, '<td valign="top">This one would have done nice in the humor II challenge too..;)</td>', 'This one would have done nice in the humor II challenge too..;)', '2004-12-15 15:43:58.000000', NULL, 1),
(1064471, 127065, 7889, '<td valign="top">Unusual but very eye catching photo. It may not go down to well with a lot of people here though. However there are some of us who appreciate people trying to produce a photograph such as this. I like the colour, the main subject and the way you have positioned it. I wish you luck</td>', 'Unusual but very eye catching photo. It may not go down to well with a lot of people here though. However there are some of us who appreciate people trying to produce a photograph such as this. I like the colour, the main subject and the way you have positioned it. I wish you luck', '2004-12-15 15:45:54.000000', NULL, 1),
(1064478, 127994, 7889, '<td valign="top">Clever idea which you have captured very well. Nothing technically wrong, colour, lighting and focus are fine.</td>', 'Clever idea which you have captured very well. Nothing technically wrong, colour, lighting and focus are fine.', '2004-12-15 15:47:57.000000', NULL, 1),
(1064483, 127873, 7889, '<td valign="top">Taking the photo from this angle has made this a very interesting shot. You have a great eye and its a very good photo.<br/></td>', 'Taking the photo from this angle has made this a very interesting shot. You have a great eye and its a very good photo.', '2004-12-15 15:48:57.000000', NULL, 1),
(1064509, 127915, 6999, '<td valign="top">Obviously meets the challenge, and is quite nicely done - I like the light and shade on the eggs themselves, but there seems a lack of colour in the grass. It lacks magic, if you follow me - whilst the light is nice, it isn''t fascinating, and the scene itself looks set-up, rather than real: actually, you know, it cries out for the shaping and compositional help you''d get from a real nest - all those curves of materials ...</td>', 'Obviously meets the challenge, and is quite nicely done - I like the light and shade on the eggs themselves, but there seems a lack of colour in the grass. It lacks magic, if you follow me - whilst the light is nice, it isn''t fascinating, and the scene itself looks set-up, rather than real: actually, you know, it cries out for the shaping and compositional help you''d get from a real nest - all those curves of materials ...', '2004-12-15 15:59:53.000000', NULL, 1),
(1064519, 127927, 6999, '<td valign="top">Nice shot - love this composition, love the light, love the balance of composition and evident care. I wish there were a greater depth of detail though - whether it''s your processing or your camera, it doesn''t have the absolute clarity one would like from a set-up shot like this. Excellent work though, with that reservation.</td>', 'Nice shot - love this composition, love the light, love the balance of composition and evident care. I wish there were a greater depth of detail though - whether it''s your processing or your camera, it doesn''t have the absolute clarity one would like from a set-up shot like this. Excellent work though, with that reservation.', '2004-12-15 16:04:14.000000', NULL, 1),
(1064547, 127954, 8970, '<td valign="top">too busy, if the top wasn''t a white cloth and it was all these pipes it would look better</td>', 'too busy, if the top wasn''t a white cloth and it was all these pipes it would look better', '2004-12-15 16:22:46.000000', NULL, 1),
(1064550, 127816, 8970, '<td valign="top">great usage of the tree trunk to frame the background</td>', 'great usage of the tree trunk to frame the background', '2004-12-15 16:26:35.000000', NULL, 1),
(1064551, 127256, 8970, '<td valign="top">would be better if the window was fully cnetered, nice color in the rocks</td>', 'would be better if the window was fully cnetered, nice color in the rocks', '2004-12-15 16:27:59.000000', NULL, 1),
(1064657, 126935, 6999, '<td valign="top">Good composition, apposite subject. Somewhat stylised for my taste - evidently set-up for the shot (or set-up for something else), but nevertheless the way you''ve shot it is strong, and it certainly fits the challenge.</td>', 'Good composition, apposite subject. Somewhat stylised for my taste - evidently set-up for the shot (or set-up for something else), but nevertheless the way you''ve shot it is strong, and it certainly fits the challenge.', '2004-12-15 17:26:03.000000', NULL, 1),
(1064662, 127954, 6999, '<td valign="top">I like this kind of found, detritus photography - the piles of stuff we have lying around, as a people. It''s a general subject I find very difficult to shoot myself, and I''m afriad this shot doesn''t quite do it for me, either. Perhaps my eye, and yours, isn''t quite trained enough in the recognistion of the simple amongst all this stuff, in the finding of compositional elements that add strength to such images - all my shots, as with this one, simply seem to be confused and lacking in much impact or sense of particular subject. I think, of rwhat its worth, that my feelings here are that you have too many different types of object in the frame, and too much extraneous mattter also, and that you haven''t really found a moment of light that enhances the shot - but quite how one would imprve it particularly remains a mystery to me. A fine attempt, but I fear not a successful one.</td>', 'I like this kind of found, detritus photography - the piles of stuff we have lying around, as a people. It''s a general subject I find very difficult to shoot myself, and I''m afriad this shot doesn''t quite do it for me, either. Perhaps my eye, and yours, isn''t quite trained enough in the recognistion of the simple amongst all this stuff, in the finding of compositional elements that add strength to such images - all my shots, as with this one, simply seem to be confused and lacking in much impact or sense of particular subject. I think, of rwhat its worth, that my feelings here are that you have too many different types of object in the frame, and too much extraneous mattter also, and that you haven''t really found a moment of light that enhances the shot - but quite how one would imprve it particularly remains a mystery to me. A fine attempt, but I fear not a successful one.', '2004-12-15 17:32:58.000000', NULL, 1),
(1064699, 127987, 6999, '<td valign="top">I like the play of this, and the watery feel. It really isn''t a field of photography that does much for me however, the near-abstract, it might, for all I see in it, as well be graphic design.</td>', 'I like the play of this, and the watery feel. It really isn''t a field of photography that does much for me however, the near-abstract, it might, for all I see in it, as well be graphic design.', '2004-12-15 18:02:35.000000', NULL, 1),
(1064707, 126917, 6999, '<td valign="top">your cropping - being so close to the torch one the left, and yet leaving that space to the right, almost implies there should be something to the left of frame that I can''t see. The image though, feels contrived, and yet doesn''t have that sense of control of environment that a set-up shot needs to make impact. There''s a sense of not quite being in focus, not quite perfect detail and sharpness, that doesn''t suit the simplicitty of the scene to my mind. Did you use a tripod for this? It looks like its handheld, and has that slight suggestion of motion blur that goes with that.</td>', 'your cropping - being so close to the torch one the left, and yet leaving that space to the right, almost implies there should be something to the left of frame that I can''t see. The image though, feels contrived, and yet doesn''t have that sense of control of environment that a set-up shot needs to make impact. There''s a sense of not quite being in focus, not quite perfect detail and sharpness, that doesn''t suit the simplicitty of the scene to my mind. Did you use a tripod for this? It looks like its handheld, and has that slight suggestion of motion blur that goes with that.', '2004-12-15 18:06:57.000000', NULL, 1),
(1064728, 127813, 6999, '<td valign="top">The sheer mess of this is exciting, and that hint of a lansdscape for those cars. Both the monochromatic and the high contrast treatments work well with the subject. Something sordid about it, something unflinching in the approach, which will, I''m sure, not go down well with Joe Voter. Not as well as it should, anyway. For all the interesting viewpoint, and the suitable treatment though, I don''t get much sense of interest from it - maybe your burning/dodging/whatever goes too far?</td>', 'The sheer mess of this is exciting, and that hint of a lansdscape for those cars. Both the monochromatic and the high contrast treatments work well with the subject. Something sordid about it, something unflinching in the approach, which will, I''m sure, not go down well with Joe Voter. Not as well as it should, anyway. For all the interesting viewpoint, and the suitable treatment though, I don''t get much sense of interest from it - maybe your burning/dodging/whatever goes too far?', '2004-12-15 18:24:06.000000', NULL, 1),
(1064730, 127604, 6999, '<td valign="top">Messy. The join of your background and surface is visible too. For such ''studio'' shots I would want a cleaner set-up - the crumbs are enormously problematic; in a situation where you do have absolute control, why not exercise it?</td>', 'Messy. The join of your background and surface is visible too. For such ''studio'' shots I would want a cleaner set-up - the crumbs are enormously problematic; in a situation where you do have absolute control, why not exercise it?', '2004-12-15 18:25:52.000000', NULL, 1),
(1064735, 127971, 6999, '<td valign="top">Neat stuff. has a sense of the over-sharpened but at very low radius that makes the fince seen almost super-imposed, and is also reminiscent of Gordon Whyte''s work. The grey winter afternoon, and light on the wood are good. Strong compositionally too.</td>', 'Neat stuff. has a sense of the over-sharpened but at very low radius that makes the fince seen almost super-imposed, and is also reminiscent of Gordon Whyte''s work. The grey winter afternoon, and light on the wood are good. Strong compositionally too.', '2004-12-15 18:28:04.000000', NULL, 1),
(1064743, 127594, 6999, '<td valign="top">Great light, and/or processing of light. Very strong compositionally - have you worked those shadows in to give the focus to the bus-stop? I think you have, but it''s so well done as to seem like a co-incidence of environment. The subject is exactly where one would want it to be, the eye is kept occupied and there remains an over-riding sense of the real, which is an especial achievement in such a morbid shot. Excellent work.</td>', 'Great light, and/or processing of light. Very strong compositionally - have you worked those shadows in to give the focus to the bus-stop? I think you have, but it''s so well done as to seem like a co-incidence of environment. The subject is exactly where one would want it to be, the eye is kept occupied and there remains an over-riding sense of the real, which is an especial achievement in such a morbid shot. Excellent work.', '2004-12-15 18:30:37.000000', NULL, 1),
(1064819, 127569, 25468, '<td valign="top">Nice idea and nice execution. 6</td>', 'Nice idea and nice execution. 6', '2004-12-15 19:31:44.000000', NULL, 1),
(1064820, 127915, 25468, '<td valign="top">I like the idea but I think the execution of it could have been better. 5</td>', 'I like the idea but I think the execution of it could have been better. 5', '2004-12-15 19:32:21.000000', NULL, 1),
(1064822, 127647, 25468, '<td valign="top">Really trippy and a great ''schindler''s list'' feel to it. 7</td>', 'Really trippy and a great ''schindler''s list'' feel to it. 7', '2004-12-15 19:33:07.000000', NULL, 1),
(1064824, 127600, 25468, '<td valign="top">Interesting idea. I doubt we''ll see any others like this. 7 for the idea alone.</td>', 'Interesting idea. I doubt we''ll see any others like this. 7 for the idea alone.', '2004-12-15 19:34:02.000000', NULL, 1),
(1064825, 127319, 25468, '<td valign="top">It''s really hard to miss this chalenge idea. I think the execution of this idea is what makes it good. 6</td>', 'It''s really hard to miss this chalenge idea. I think the execution of this idea is what makes it good. 6', '2004-12-15 19:35:04.000000', NULL, 1),
(1064830, 126939, 25468, '<td valign="top">I didn''t like how bright the background turned out. I also thought the cropping should concentrate more on the broken string. I think people would have known exactly what it was without the entire instrument in the photo. 5</td>', 'I didn''t like how bright the background turned out. I also thought the cropping should concentrate more on the broken string. I think people would have known exactly what it was without the entire instrument in the photo. 5', '2004-12-15 19:36:57.000000', NULL, 1),
(1064832, 127904, 25468, '<td valign="top">Ahh, the infamous factory windows. I smashed a few hundred of these in my day. I would have like this more if it were more artsy. Perhaps less light or a different angle. Would have got a higher score from me that way. 5</td>', 'Ahh, the infamous factory windows. I smashed a few hundred of these in my day. I would have like this more if it were more artsy. Perhaps less light or a different angle. Would have got a higher score from me that way. 5', '2004-12-15 19:38:01.000000', NULL, 1),
(1064838, 127475, 25468, '<td valign="top">I didn''t like the title though that doesn''t hurt the score with me. The subject seems more of the winning the ribbon than the broken pencil. I thought IMHO that it should have been more on the pencil, to me the book isn''t needed. 5</td>', 'I didn''t like the title though that doesn''t hurt the score with me. The subject seems more of the winning the ribbon than the broken pencil. I thought IMHO that it should have been more on the pencil, to me the book isn''t needed. 5', '2004-12-15 19:39:49.000000', NULL, 1),
(1064842, 127648, 25468, '<td valign="top">I would have given this a higher score had it been on the street or something like that. I think this is too ''set up'' for my tastes (or at least appears to be). 5</td>', 'I would have given this a higher score had it been on the street or something like that. I think this is too ''set up'' for my tastes (or at least appears to be). 5', '2004-12-15 19:40:57.000000', NULL, 1),
(1064844, 126334, 25468, '<td valign="top">I really like stuff that makes you think. This gets my imagination going, wondering what that dream is about. This is IMHO not the best shot of the bunch, but it does get the mind going... 6 for that.</td>', 'I really like stuff that makes you think. This gets my imagination going, wondering what that dream is about. This is IMHO not the best shot of the bunch, but it does get the mind going... 6 for that.', '2004-12-15 19:42:11.000000', NULL, 1),
(1064846, 127871, 25468, '<td valign="top">Another interesting idea. I''ve seen alot of this type of thing growing up, my father being a tow truck driver and all. Spidered windshields to me signify a greater problem. I''m not sure other people will see what I saw, but I like it and the message I recieved from it. 7</td>', 'Another interesting idea. I''ve seen alot of this type of thing growing up, my father being a tow truck driver and all. Spidered windshields to me signify a greater problem. I''m not sure other people will see what I saw, but I like it and the message I recieved from it. 7', '2004-12-15 19:43:53.000000', NULL, 1),
(1064849, 127858, 25468, '<td valign="top">Sort of makes you wonder why it still stands. I think the shot is a little too bright for me. I would like to see more of your creativity in this. This to me had a real Photo-journalism feel to it. Good job on the find, just didn''t smack the crap out of me. 6</td>', 'Sort of makes you wonder why it still stands. I think the shot is a little too bright for me. I would like to see more of your creativity in this. This to me had a real Photo-journalism feel to it. Good job on the find, just didn''t smack the crap out of me. 6', '2004-12-15 19:45:46.000000', NULL, 1),
(1064851, 127749, 25468, '<td valign="top">I like the idea, but not for this challenge. I don''t really see this as representing something broken. Now if it [the door] were closed or hanging off the hinges I would have voted higher. 4</td>', 'I like the idea, but not for this challenge. I don''t really see this as representing something broken. Now if it [the door] were closed or hanging off the hinges I would have voted higher. 4', '2004-12-15 19:46:56.000000', NULL, 1),
(1064857, 127356, 25468, '<td valign="top">I like this shot. I do on the other hand think the bottom right hand corner is a little bright. I would have used a polarizer to remove that glare too, but that''s just me. 5</td>', 'I like this shot. I do on the other hand think the bottom right hand corner is a little bright. I would have used a polarizer to remove that glare too, but that''s just me. 5', '2004-12-15 19:48:21.000000', NULL, 1),
(1064860, 127560, 25468, '<td valign="top">I wasn''t really feeling your idea. 5</td>', 'I wasn''t really feeling your idea. 5', '2004-12-15 19:50:01.000000', NULL, 1),
(1064890, 127356, 20779, '<td valign="top">One of two lightbulb shots that really moved me in the challenge.  There is real emotion and movement here, along with technical excellence. I love the shift from dark to light as you gaze from one side to the other. Terrific composition within the frame. Bold colors. The frame really works for me on this one.</td>', 'One of two lightbulb shots that really moved me in the challenge.  There is real emotion and movement here, along with technical excellence. I love the shift from dark to light as you gaze from one side to the other. Terrific composition within the frame. Bold colors. The frame really works for me on this one.', '2004-12-15 20:28:55.000000', NULL, 1),
(1064891, 127888, 25468, '<td valign="top">I guess this chair crossed paths with subway''s Jared before Jared was subway''s. Definately broken. 6</td>', 'I guess this chair crossed paths with subway''s Jared before Jared was subway''s. Definately broken. 6', '2004-12-15 20:29:14.000000', NULL, 1),
(1064892, 127850, 25468, '<td valign="top">I really like seeing the junk in the background. Would have voted higher had the shot been framed through one pane of glass. 6</td>', 'I really like seeing the junk in the background. Would have voted higher had the shot been framed through one pane of glass. 6', '2004-12-15 20:30:07.000000', NULL, 1),
(1064893, 127806, 20779, '<td valign="top">Extremely emotive and well-composed piece that melds art with photography. The woman''s eye is caught with just the right perspective to lead us into thinking what has happened in her life or sight.</td>', 'Extremely emotive and well-composed piece that melds art with photography. The woman''s eye is caught with just the right perspective to lead us into thinking what has happened in her life or sight.', '2004-12-15 20:31:01.000000', NULL, 1),
(1064894, 127744, 25468, '<td valign="top">To me the most interesting part is the truck, and it''s also IMHO what made this fit with ''broken''. I would have concentrated more on the truck itself but a good idea never the less.</td>', 'To me the most interesting part is the truck, and it''s also IMHO what made this fit with ''broken''. I would have concentrated more on the truck itself but a good idea never the less.', '2004-12-15 20:31:04.000000', NULL, 1),
(1064896, 126448, 25468, '<td valign="top">haha, awesome idea. sort of a real birthday countdown. 8</td>', 'haha, awesome idea. sort of a real birthday countdown. 8', '2004-12-15 20:31:36.000000', NULL, 1),
(1064897, 127816, 25468, '<td valign="top">I think the borders over dominates this photo. I was torn by the ''misty'' effect within this photo. Part of me liked it, while the other part of me thought it ruined the shot. I also think you could have done more justice cropped in on the actual broken limb. I think the background is also quite distracting. 5</td>', 'I think the borders over dominates this photo. I was torn by the ''misty'' effect within this photo. Part of me liked it, while the other part of me thought it ruined the shot. I also think you could have done more justice cropped in on the actual broken limb. I think the background is also quite distracting. 5', '2004-12-15 20:34:05.000000', NULL, 1),
(1064898, 127813, 20779, '<td valign="top">As a surviivor of three major collisions, Ithis image tore at me when I first saw it. I calmed down as I saw that time had passed by for  the cars I am viewing, and I am looking out through past tragedy possibly, or just decomposition. I love the creativity and tones used here to give a unique perspective and experience to the viewer.</td>', 'As a surviivor of three major collisions, Ithis image tore at me when I first saw it. I calmed down as I saw that time had passed by for  the cars I am viewing, and I am looking out through past tragedy possibly, or just decomposition. I love the creativity and tones used here to give a unique perspective and experience to the viewer.', '2004-12-15 20:34:32.000000', NULL, 1),
(1064899, 127474, 25468, '<td valign="top">I like this kind of humorous art, be it drawn or photographed or twisted out of an old garbage can. Great Job.</td>', 'I like this kind of humorous art, be it drawn or photographed or twisted out of an old garbage can. Great Job.', '2004-12-15 20:35:35.000000', NULL, 1),
(1064900, 127989, 25468, '<td valign="top">I bet most people see the pencil as the broken idea. I on the other hand see a hidden meaning. I see his patience as the subject. 6</td>', 'I bet most people see the pencil as the broken idea. I on the other hand see a hidden meaning. I see his patience as the subject. 6', '2004-12-15 20:36:39.000000', NULL, 1),
(1064901, 127865, 25468, '<td valign="top">I like the idea I think you were trying to get accross. 7 for that</td>', 'I like the idea I think you were trying to get accross. 7 for that', '2004-12-15 20:38:43.000000', NULL, 1),
(1064902, 127660, 25468, '<td valign="top">More old and rusted that broken. Great composition though. 6</td>', 'More old and rusted that broken. Great composition though. 6', '2004-12-15 20:39:14.000000', NULL, 1),
