(1066147, 127516, 11899, '<td valign="top">Interesting ...its all very dark and she''s somewhat lost in the composition, but I like the idea.</td>', 'Interesting ...its all very dark and she''s somewhat lost in the composition, but I like the idea.', '2004-12-16 16:53:29.000000', NULL, 1),
(1066149, 127855, 11899, '<td valign="top">Well done...high score from me.</td>', 'Well done...high score from me.', '2004-12-16 16:54:28.000000', NULL, 1),
