(1068225, 128010, 30861, '<td valign="top">An interesting take. Nothing is actually broken, but the image is broken up for sure.</td>', 'An interesting take. Nothing is actually broken, but the image is broken up for sure.', '2004-12-18 18:15:49.000000', NULL, 1),
(1068226, 127905, 10047, '<td valign="top">Lighting might not have been so harsh if you had moved it out to the back yard, and set up the shot with a background.</td>', 'Lighting might not have been so harsh if you had moved it out to the back yard, and set up the shot with a background.', '2004-12-18 18:15:55.000000', NULL, 1),
(1068227, 126712, 30861, '<td valign="top">Too much jumble, no focus on the ice edges that are broken. Needs some work with a levels layer.</td>', 'Too much jumble, no focus on the ice edges that are broken. Needs some work with a levels layer.', '2004-12-18 18:17:12.000000', NULL, 1),
(1068229, 127991, 10047, '<td valign="top">Indoor lighting seems a bit harsh. I might have moved the candies closer together in the same arrangement and tried for more detail.</td>', 'Indoor lighting seems a bit harsh. I might have moved the candies closer together in the same arrangement and tried for more detail.', '2004-12-18 18:17:54.000000', NULL, 1),
(1068230, 127862, 30861, '<td valign="top">Technically interesting, graphically absurd. The colors are totally over the top.</td>', 'Technically interesting, graphically absurd. The colors are totally over the top.', '2004-12-18 18:18:04.000000', NULL, 1),
(1068231, 127848, 30861, '<td valign="top">haunting</td>', 'haunting', '2004-12-18 18:18:20.000000', NULL, 1),
(1068232, 127332, 30861, '<td valign="top">What''s broken?</td>', 'What''s broken?', '2004-12-18 18:18:38.000000', NULL, 1),
(1068233, 126958, 30861, '<td valign="top">The border adds nothing. The light is flat. The colors are blah. It''s all subject, no art.</td>', 'The border adds nothing. The light is flat. The colors are blah. It''s all subject, no art.', '2004-12-18 18:19:28.000000', NULL, 1),
(1068234, 127863, 10047, '<td valign="top">There must be a real trick to shooting eggs. I know I haven''t had much luck. The arrangement is well done, but the yolk and white don''t seem natural.</td>', 'There must be a real trick to shooting eggs. I know I haven''t had much luck. The arrangement is well done, but the yolk and white don''t seem natural.', '2004-12-18 18:20:15.000000', NULL, 1),
(1068235, 127971, 30861, '<td valign="top">Almost there... almost. If it were cropped so there were almost no sky and there was correspondingly more foreground, it could be very nice. Also, the fence itself needs to have some of the ble/cyan removed and the yellow/red bumped up, so it pops a bit more.</td>', 'Almost there... almost. If it were cropped so there were almost no sky and there was correspondingly more foreground, it could be very nice. Also, the fence itself needs to have some of the ble/cyan removed and the yellow/red bumped up, so it pops a bit more.', '2004-12-18 18:21:34.000000', NULL, 1),
(1068237, 127356, 10047, '<td valign="top">The lighting seems harsh, but maybe that is the intent. I think I would have tried it in a "light tent" to cut down on the glare.</td>', 'The lighting seems harsh, but maybe that is the intent. I think I would have tried it in a "light tent" to cut down on the glare.', '2004-12-18 18:22:00.000000', NULL, 1),
(1068238, 127869, 30861, '<td valign="top">cropping is a little tight top and left. I''d like to see the full course of upended bricks above plus a little of the running course, and I''d want to have a little more space to the left of the window as well. Still, a sweet image.</td>', 'cropping is a little tight top and left. I''d like to see the full course of upended bricks above plus a little of the running course, and I''d want to have a little more space to the left of the window as well. Still, a sweet image.', '2004-12-18 18:23:01.000000', NULL, 1),
(1068239, 127482, 30861, '<td valign="top">I need some ghost of detail in the black areas, please.</td>', 'I need some ghost of detail in the black areas, please.', '2004-12-18 18:23:25.000000', NULL, 1),
(1068240, 127082, 30861, '<td valign="top">fine tonalities. The nearly vertical, elongated, left edge of the hand bothers me, especially inasmuch as it''s very nearly in the center of the image. I like the slight upward tilt of the visible eye.</td>', 'fine tonalities. The nearly vertical, elongated, left edge of the hand bothers me, especially inasmuch as it''s very nearly in the center of the image. I like the slight upward tilt of the visible eye.', '2004-12-18 18:25:15.000000', NULL, 1),
(1068242, 127813, 30861, '<td valign="top">conceptually interesting, compositoonally a muddle</td>', 'conceptually interesting, compositoonally a muddle', '2004-12-18 18:25:47.000000', NULL, 1),
(1068243, 127832, 10047, '<td valign="top">That brings back memories. The form and handicap sheet seem a bit washed out. I might have tried a darker background and diffused lighting.</td>', 'That brings back memories. The form and handicap sheet seem a bit washed out. I might have tried a darker background and diffused lighting.', '2004-12-18 18:26:16.000000', NULL, 1),
(1068244, 127857, 30861, '<td valign="top">this doesn''t work well for me, it''s too "average" in tonality, hue, and composition, a deadly mix.</td>', 'this doesn''t work well for me, it''s too "average" in tonality, hue, and composition, a deadly mix.', '2004-12-18 18:26:42.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1068245, 127811, 30861, '<td valign="top">Crisp and ethereal, a little pat for my tastes though</td>', 'Crisp and ethereal, a little pat for my tastes though', '2004-12-18 18:27:10.000000', NULL, 1),
(1068247, 127346, 30861, '<td valign="top">Very nice. Makes me laugh.</td>', 'Very nice. Makes me laugh.', '2004-12-18 18:27:43.000000', NULL, 1),
(1068248, 127482, 10047, '<td valign="top">A little soft. I might have cropped out more of the dead space in the upper left to see what impact it had.</td>', 'A little soft. I might have cropped out more of the dead space in the upper left to see what impact it had.', '2004-12-18 18:28:16.000000', NULL, 1),
(1068249, 126761, 30861, '<td valign="top">shouldn''t the ink be red as well? I''d think that would take it over the edge...</td>', 'shouldn''t the ink be red as well? I''d think that would take it over the edge...', '2004-12-18 18:28:20.000000', NULL, 1),
(1068251, 127657, 10047, '<td valign="top">I think I would boiled off the meat and cartiledge to try for a cleaner and crisper look. The lighting has also washed out the top a little.</td>', 'I think I would boiled off the meat and cartiledge to try for a cleaner and crisper look. The lighting has also washed out the top a little.', '2004-12-18 18:31:43.000000', NULL, 1),
(1068253, 127758, 22734, '<td valign="top">Returning for comments:<br/>The technique here is very adept and the composition very pleasing. there is clarity to spare. Bumping up</td>', 'Returning for comments:The technique here is very adept and the composition very pleasing. there is clarity to spare. Bumping up', '2004-12-18 18:32:49.000000', NULL, 1),
(1068256, 127988, 10047, '<td valign="top">Is that a Mustang? Looks like you have some jaggies along the A-pillar and windshield trim. Is that caused by cropping too tight? I might have tried changing the gray wall to a different color or shade.</td>', 'Is that a Mustang? Looks like you have some jaggies along the A-pillar and windshield trim. Is that caused by cropping too tight? I might have tried changing the gray wall to a different color or shade.', '2004-12-18 18:35:05.000000', NULL, 1),
(1068257, 127863, 22734, '<td valign="top">Returning for comments:<br/>Very neatly done. it looks like an ad and as you know these shots require skill.<br/>The textures are all superb and the egg shells and insides add a dramatic contrast to the white, gray background. Bumping up.</td>', 'Returning for comments:Very neatly done. it looks like an ad and as you know these shots require skill.The textures are all superb and the egg shells and insides add a dramatic contrast to the white, gray background. Bumping up.', '2004-12-18 18:35:12.000000', NULL, 1),
(1068258, 127662, 22734, '<td valign="top">Returning for comments:<br/>Scary little thing. lol. A very well detailed capture. Bumping up.</td>', 'Returning for comments:Scary little thing. lol. A very well detailed capture. Bumping up.', '2004-12-18 18:36:19.000000', NULL, 1),
(1068261, 127852, 22734, '<td valign="top">Returning for comments:<br/>While of a rather dark realm, the technique here is great and the color mood sways gently the viewer. Bumping up.</td>', 'Returning for comments:While of a rather dark realm, the technique here is great and the color mood sways gently the viewer. Bumping up.', '2004-12-18 18:38:21.000000', NULL, 1),
(1068262, 127893, 10047, '<td valign="top">More than a few broken heart photos in the challenge, but I think this is well done. Somebody has nice handwriting. Anyway, I would have tried moving the ring towrd the Dear John a bit more and try to get them both in focus.</td>', 'More than a few broken heart photos in the challenge, but I think this is well done. Somebody has nice handwriting. Anyway, I would have tried moving the ring towrd the Dear John a bit more and try to get them both in focus.', '2004-12-18 18:38:23.000000', NULL, 1),
(1068263, 126372, 22734, '<td valign="top">Returning for comments:<br/>If it is coming at me and i have a bruised ankle, yeah, let it be broken. lol Bumping up.</td>', 'Returning for comments:If it is coming at me and i have a bruised ankle, yeah, let it be broken. lol Bumping up.', '2004-12-18 18:39:47.000000', NULL, 1),
(1068270, 127319, 22734, '<td valign="top">Returning for comments:<br/>Very clear and I even hear the glass swishing away. Good capture. Bumping up.</td>', 'Returning for comments:Very clear and I even hear the glass swishing away. Good capture. Bumping up.', '2004-12-18 18:42:58.000000', NULL, 1),
(1068278, 127356, 22734, '<td valign="top">Returning for comments:<br/>Nice title. Imagine if there was a figure in the background with a depressed look. Ah, well, that is another image. Nice job here as is. Bumping up.</td>', 'Returning for comments:Nice title. Imagine if there was a figure in the background with a depressed look. Ah, well, that is another image. Nice job here as is. Bumping up.', '2004-12-18 18:45:01.000000', NULL, 1),
(1068319, 128003, 30861, '<td valign="top">seems clichéd to me, and it''s losing detail to the top where we need it most.</td>', 'seems clichéd to me, and it''s losing detail to the top where we need it most.', '2004-12-18 19:31:51.000000', NULL, 1),
(1068320, 126390, 30861, '<td valign="top">I don''t see this as broken, I see it as mending.</td>', 'I don''t see this as broken, I see it as mending.', '2004-12-18 19:32:30.000000', NULL, 1),
(1068321, 126802, 30861, '<td valign="top">handsome image, but the cropping leaves precisely 50% of the image black; this is too static.</td>', 'handsome image, but the cropping leaves precisely 50% of the image black; this is too static.', '2004-12-18 19:33:07.000000', NULL, 1),
(1068322, 127904, 30861, '<td valign="top">Ahhhh... Very very nice. Compositionally anyway... I wonder if the hue/saturation could be improved.</td>', 'Ahhhh... Very very nice. Compositionally anyway... I wonder if the hue/saturation could be improved.', '2004-12-18 19:34:12.000000', NULL, 1),
(1068323, 127835, 30861, '<td valign="top">another one where the right half of the image is a non-factor, like the egg picture.</td>', 'another one where the right half of the image is a non-factor, like the egg picture.', '2004-12-18 19:34:47.000000', NULL, 1),
(1068326, 127554, 30861, '<td valign="top">The cropping baffles me here. Why so aggressively horizontal if there''s nothing THERE to see? At least in this case, the actual image divides to thirds, not halves, the frame.</td>', 'The cropping baffles me here. Why so aggressively horizontal if there''s nothing THERE to see? At least in this case, the actual image divides to thirds, not halves, the frame.', '2004-12-18 19:35:44.000000', NULL, 1),
(1068327, 127899, 30861, '<td valign="top">snapshot</td>', 'snapshot', '2004-12-18 19:35:55.000000', NULL, 1),
(1068328, 127254, 30861, '<td valign="top">Way too flat, toanlly. The composition has great promise; it should be shot in a much more revealing light.</td>', 'Way too flat, toanlly. The composition has great promise; it should be shot in a much more revealing light.', '2004-12-18 19:36:51.000000', NULL, 1),
(1068329, 127597, 30861, '<td valign="top">I get the feeling I''d love this if the colors were natural; as a negative image it doesn''t work for me.</td>', 'I get the feeling I''d love this if the colors were natural; as a negative image it doesn''t work for me.', '2004-12-18 19:37:28.000000', NULL, 1),
(1068330, 127521, 30861, '<td valign="top">Colors way too saturated here. For no good reason that I can see. Love the bird. Composition is to "regular"</td>', 'Colors way too saturated here. For no good reason that I can see. Love the bird. Composition is to "regular"', '2004-12-18 19:38:27.000000', NULL, 1),
(1068331, 127610, 30861, '<td valign="top">Sweet &amp; strong</td>', 'Sweet & strong', '2004-12-18 19:38:44.000000', NULL, 1),
(1068334, 127662, 30861, '<td valign="top">hideous lighting, questionable validity in terms of "broken".</td>', 'hideous lighting, questionable validity in terms of "broken".', '2004-12-18 19:40:02.000000', NULL, 1),
(1068335, 127854, 30861, '<td valign="top">A snapshot anecdote. Where''s the art or craft in this?</td>', 'A snapshot anecdote. Where''s the art or craft in this?', '2004-12-18 19:40:34.000000', NULL, 1),
(1068336, 128009, 30861, '<td valign="top">So greasy it''s almost good, but the lighting is hopeless.</td>', 'So greasy it''s almost good, but the lighting is hopeless.', '2004-12-18 19:41:13.000000', NULL, 1),
(1068337, 127871, 30861, '<td valign="top">A sweet abstract.</td>', 'A sweet abstract.', '2004-12-18 19:41:33.000000', NULL, 1),
(1068338, 127958, 30861, '<td valign="top">I wish like hell this had more foreground depth of field and a hair less crop to the tail. Is "dead" the same as "broken"?</td>', 'I wish like hell this had more foreground depth of field and a hair less crop to the tail. Is "dead" the same as "broken"?', '2004-12-18 19:42:22.000000', NULL, 1),
(1068339, 127943, 30861, '<td valign="top">Conceptually nice, lack of overall sharpness a critical failure.</td>', 'Conceptually nice, lack of overall sharpness a critical failure.', '2004-12-18 19:43:18.000000', NULL, 1),
(1068340, 127900, 30861, '<td valign="top">Thumbs up on this.</td>', 'Thumbs up on this.', '2004-12-18 19:43:40.000000', NULL, 1),
(1068342, 127474, 30861, '<td valign="top">amusing as hell. I wish it were better integrated into a background, perhaps of bad digital photo prints...</td>', 'amusing as hell. I wish it were better integrated into a background, perhaps of bad digital photo prints...', '2004-12-18 19:44:18.000000', NULL, 1),
(1068346, 127255, 30861, '<td valign="top">I like this. Leach out a little of the sickly yellow/green cast ond I''d like it more.</td>', 'I like this. Leach out a little of the sickly yellow/green cast ond I''d like it more.', '2004-12-18 19:46:00.000000', NULL, 1),
(1068369, 127442, 30869, '<td valign="top">cool picture...definitely not easy to capture.</td>', 'cool picture...definitely not easy to capture.', '2004-12-18 20:23:49.000000', NULL, 1),
(1068375, 127988, 6999, '<td valign="top">Good shot, though ti''s a shame about the jaffies around the screen frame. It''s a neat compsition too, and I think you do very well not to fall into the common trap of trying t show the whole car.</td>', 'Good shot, though ti''s a shame about the jaffies around the screen frame. It''s a neat compsition too, and I think you do very well not to fall into the common trap of trying t show the whole car.', '2004-12-18 20:35:01.000000', NULL, 1),
(1068376, 127848, 6999, '<td valign="top">Nice composition - although I think your prcessing, certainly in terms of the darkening of the background, could use more work - it''s really quite visible, and it looks like a mistake rather than deliberate. Likewise there seems t be a lighter area around the lightbulb that smacks of selection inaccuracies. Not badly lit at all - some real shape here.</td>', 'Nice composition - although I think your prcessing, certainly in terms of the darkening of the background, could use more work - it''s really quite visible, and it looks like a mistake rather than deliberate. Likewise there seems t be a lighter area around the lightbulb that smacks of selection inaccuracies. Not badly lit at all - some real shape here.', '2004-12-18 20:37:32.000000', NULL, 1),
(1068379, 126647, 6999, '<td valign="top">Good light, good tonality (although it seems to very oddly across the frame). Strong sense of texture and age - composition seems a touch forced though.</td>', 'Good light, good tonality (although it seems to very oddly across the frame). Strong sense of texture and age - composition seems a touch forced though.', '2004-12-18 20:39:02.000000', NULL, 1),
(1068380, 127646, 6999, '<td valign="top">great timinig, and prettty good execution of the shot. I think your processing could use work at leaast in dpc terms - the body of the lamp could be cleaner, and possibly brughter for impact, and the background could be taken to black quite easily.</td>', 'great timinig, and prettty good execution of the shot. I think your processing could use work at leaast in dpc terms - the body of the lamp could be cleaner, and possibly brughter for impact, and the background could be taken to black quite easily.', '2004-12-18 20:40:43.000000', NULL, 1),
(1068381, 127745, 6999, '<td valign="top">Excellent light, good sense of texture, and I love that background for this. Spot on exposure, to my eye.</td>', 'Excellent light, good sense of texture, and I love that background for this. Spot on exposure, to my eye.', '2004-12-18 20:41:46.000000', NULL, 1),
(1068384, 127627, 6999, '<td valign="top">Difficult to achieve I know, but there could be more sense of texture in the material of the door itself, no? Just to add that real edge of contrast to the metal of the handle? It has a feeling of a half-stop or so over-exposure, and that that has leeched away some of the tonality and finer detail in those textures. Nice work all the same.</td>', 'Difficult to achieve I know, but there could be more sense of texture in the material of the door itself, no? Just to add that real edge of contrast to the metal of the handle? It has a feeling of a half-stop or so over-exposure, and that that has leeched away some of the tonality and finer detail in those textures. Nice work all the same.', '2004-12-18 20:43:50.000000', NULL, 1),
(1068385, 127597, 6999, '<td valign="top">Broken colouration too, is that it? A technically fine shot, although I have a resistance to the subject matter which won''t cost you anything - but I have a stronger resistance to the wacky colouring: it makes the flag an unfamiliar thing, and yet your title suggests that it should be an immediately familiar one. Maybe the impression of confusion is one you wanted to sow, but to my mind it is incoherent.</td>', 'Broken colouration too, is that it? A technically fine shot, although I have a resistance to the subject matter which won''t cost you anything - but I have a stronger resistance to the wacky colouring: it makes the flag an unfamiliar thing, and yet your title suggests that it should be an immediately familiar one. Maybe the impression of confusion is one you wanted to sow, but to my mind it is incoherent.', '2004-12-18 20:46:39.000000', NULL, 1),
(1068386, 127341, 6999, '<td valign="top">Great colour, strong composition. It lacks something for me - just that edge of real shape from light perhaps. Nice work.</td>', 'Great colour, strong composition. It lacks something for me - just that edge of real shape from light perhaps. Nice work.', '2004-12-18 20:48:14.000000', NULL, 1),
(1068388, 127564, 6999, '<td valign="top">Almost lovely, and almost wonderful execution - it would be faultless without having taken the sharpening quite as far as it has been. Proper high-key work, solid composition. Dramatic certainly, but in terms of substance ... I''m not sure.</td>', 'Almost lovely, and almost wonderful execution - it would be faultless without having taken the sharpening quite as far as it has been. Proper high-key work, solid composition. Dramatic certainly, but in terms of substance ... I''m not sure.', '2004-12-18 20:51:37.000000', NULL, 1),
(1068398, 127888, 25397, '<td valign="top">The cracks in the ground are really effective.</td>', 'The cracks in the ground are really effective.', '2004-12-18 21:20:08.000000', NULL, 1),
(1068402, 127641, 25397, '<td valign="top">I think its really neat how the footprints seem to be more plentiful in the area of the broken part of the bridge.</td>', 'I think its really neat how the footprints seem to be more plentiful in the area of the broken part of the bridge.', '2004-12-18 21:23:57.000000', NULL, 1),
(1068403, 127570, 25397, '<td valign="top">The softness of the picture makes me feel sorry for this rusted thing that has probably seen many wars.<br/> <br/>It''s a great picture. :)<br/>I also like the old tire in the very very very backround,</td>', 'The softness of the picture makes me feel sorry for this rusted thing that has probably seen many wars. It''s a great picture. :)I also like the old tire in the very very very backround,', '2004-12-18 21:26:53.000000', NULL, 1),
(1068404, 127484, 25397, '<td valign="top">This is such a powerful photo.  It seems that the baby stroller is ignored and that brings the emotional quality.</td>', 'This is such a powerful photo.  It seems that the baby stroller is ignored and that brings the emotional quality.', '2004-12-18 21:29:11.000000', NULL, 1),
(1068405, 127482, 25397, '<td valign="top">I would have liked to see a bit more of the instrument.</td>', 'I would have liked to see a bit more of the instrument.', '2004-12-18 21:30:15.000000', NULL, 1),
(1068407, 127655, 25397, '<td valign="top">This is really interesting, I like it.</td>', 'This is really interesting, I like it.', '2004-12-18 21:33:55.000000', NULL, 1),
(1068409, 127990, 25397, '<td valign="top">Reminds me of when my brother used to tortue my stuffed animals. The tight crop works well.</td>', 'Reminds me of when my brother used to tortue my stuffed animals. The tight crop works well.', '2004-12-18 21:35:28.000000', NULL, 1),
(1068410, 127541, 25397, '<td valign="top">Don''t pick it up! It''s Sauron''s ring! It will destroy you!</td>', 'Don''t pick it up! It''s Sauron''s ring! It will destroy you!', '2004-12-18 21:36:33.000000', NULL, 1),
(1068413, 127900, 25397, '<td valign="top">This is just such a strong image I added it to my favourites. :)</td>', 'This is just such a strong image I added it to my favourites. :)', '2004-12-18 21:38:00.000000', NULL, 1),
(1068414, 126334, 25397, '<td valign="top">The blood looks good (is it supposed to be blood?) what did you use for it?</td>', 'The blood looks good (is it supposed to be blood?) what did you use for it?', '2004-12-18 21:38:46.000000', NULL, 1),
(1068416, 127860, 25397, '<td valign="top">We can certainly see what broke the mirror...<br/> <br/>Just kidding ;-)<br/>I''m curious, how did you ever take this without getting the camera in the reflection? It''s really cool.</td>', 'We can certainly see what broke the mirror... Just kidding ;-)I''m curious, how did you ever take this without getting the camera in the reflection? It''s really cool.', '2004-12-18 21:40:16.000000', NULL, 1),
(1068418, 127841, 25397, '<td valign="top">That has got to be the creepyest pinata I have ever seen.  I would be too afraid to hit it because I would be in fear of it drowning me in my own blood then wearing my skin.</td>', 'That has got to be the creepyest pinata I have ever seen.  I would be too afraid to hit it because I would be in fear of it drowning me in my own blood then wearing my skin.', '2004-12-18 21:41:38.000000', NULL, 1),
(1068419, 127848, 25397, '<td valign="top">There is a mysterious aurua around the light bulb.</td>', 'There is a mysterious aurua around the light bulb.', '2004-12-18 21:43:09.000000', NULL, 1),
(1068420, 127357, 25397, '<td valign="top">Wow, I''m sure some people will complain about the positioning of the moon but I think it looks great where it is.</td>', 'Wow, I''m sure some people will complain about the positioning of the moon but I think it looks great where it is.', '2004-12-18 21:43:54.000000', NULL, 1),
(1068421, 127915, 25397, '<td valign="top">Velociraptor eggs! Spray pesticides everywhere before ''Jurassic Park'' happens to you!</td>', 'Velociraptor eggs! Spray pesticides everywhere before ''Jurassic Park'' happens to you!', '2004-12-18 21:45:39.000000', NULL, 1),
(1068422, 127893, 25397, '<td valign="top">Poor John...</td>', 'Poor John...', '2004-12-18 21:47:00.000000', NULL, 1),
(1068426, 127352, 25397, '<td valign="top">One of the more interesting of the many light bulb shots.</td>', 'One of the more interesting of the many light bulb shots.', '2004-12-18 21:48:22.000000', NULL, 1),
(1068428, 127669, 25397, '<td valign="top">Is it a better bargain then Jesus'' hand on ebay?</td>', 'Is it a better bargain then Jesus'' hand on ebay?', '2004-12-18 21:49:37.000000', NULL, 1),
(1068429, 126448, 25397, '<td valign="top">Oh man thats such a good idea.</td>', 'Oh man thats such a good idea.', '2004-12-18 21:50:31.000000', NULL, 1),
(1068430, 127346, 25397, '<td valign="top">This happened to me once, glue and windex works good.</td>', 'This happened to me once, glue and windex works good.', '2004-12-18 21:51:31.000000', NULL, 1),
(1068448, 127872, 8624, '<td valign="top">great color and sharpness! subject is kinda creepy. I also wish the doll''s foot was in frame.</td>', 'great color and sharpness! subject is kinda creepy. I also wish the doll''s foot was in frame.', '2004-12-18 22:27:36.000000', NULL, 1),
(1068449, 127980, 23511, '<td valign="top">Yes, yes, yes, yes!!!!!</td>', 'Yes, yes, yes, yes!!!!!', '2004-12-18 22:27:59.000000', NULL, 1),
(1068452, 126448, 7810, '<td valign="top">Great idea...this shot should do very well. My fav  for the challenge</td>', 'Great idea...this shot should do very well. My fav  for the challenge', '2004-12-18 22:34:45.000000', NULL, 1),
(1068544, 127600, 19936, '<td valign="top">Oh, the poor kit lens!  What did you do to it!  Very funny.  Good composition and focus.  Not sure about the saucer but that is being a little critical.  Good job.</td>', 'Oh, the poor kit lens!  What did you do to it!  Very funny.  Good composition and focus.  Not sure about the saucer but that is being a little critical.  Good job.', '2004-12-19 00:52:11.000000', NULL, 1),
