(1068636, 127357, 13749, '<td valign="top">wow. powerful image.  sky looks a bit artificial, but i really like your choice to silhouette here.</td>', 'wow. powerful image.  sky looks a bit artificial, but i really like your choice to silhouette here.', '2004-12-19 02:30:42.000000', NULL, 1),
(1068637, 127619, 13749, '<td valign="top">very interesting and compelling find.  wish the background was slightly more out of focus, but not sure if that was possible for you at the time.  nice work.</td>', 'very interesting and compelling find.  wish the background was slightly more out of focus, but not sure if that was possible for you at the time.  nice work.', '2004-12-19 02:32:31.000000', NULL, 1),
