(1070210, 127346, 14012, '<td valign="top">Very good work Dan...very creative. Congrats on your well deserved Blue.</td>', 'Very good work Dan...very creative. Congrats on your well deserved Blue.', '2004-12-20 08:21:03.000000', NULL, 0),
