(1070511, 127346, 1570, '<td valign="top">Congratulations, you deserve this!</td>', 'Congratulations, you deserve this!', '2004-12-20 11:39:33.000000', NULL, 0),
(1070521, 126448, 25754, '<td valign="top">hehe, egg themed pics are the way to go!</td>', 'hehe, egg themed pics are the way to go!', '2004-12-20 11:43:24.000000', NULL, 0),
(1070575, 127346, 25388, '<td valign="top">Congratulations Dan, great creativity and technicals; well deserved and this was my only 10 of the challenge.</td>', 'Congratulations Dan, great creativity and technicals; well deserved and this was my only 10 of the challenge.', '2004-12-20 12:07:10.000000', NULL, 0),
(1070623, 127602, 28188, '<td valign="top">This is one picture I really wish I hadn''t entered.  When I submitted it, I thought that it would be evident from the title that it was taken during an exercise and with  hindsight, "Firebrigade on exercise" would have been a better title.  The comments show however that I was mistaken and that many believed it to have been taken at the site of an actual accident.  <br/> <br/>To those who were hurt by my photo or offended by it, I apologize.  It was not my intention.</td>', 'This is one picture I really wish I hadn''t entered.  When I submitted it, I thought that it would be evident from the title that it was taken during an exercise and with  hindsight, "Firebrigade on exercise" would have been a better title.  The comments show however that I was mistaken and that many believed it to have been taken at the site of an actual accident.   To those who were hurt by my photo or offended by it, I apologize.  It was not my intention.', '2004-12-20 12:46:06.000000', NULL, 0),
(1070662, 127346, 12896, '<td valign="top">I didnt realize editing to this degree was aloud within the rules on DPC.  Regardless, damn nice job and very original!</td>', 'I didnt realize editing to this degree was aloud within the rules on DPC.  Regardless, damn nice job and very original!', '2004-12-20 13:23:30.000000', NULL, 0),
(1070760, 127346, 4482, '<td valign="top">WOW! Daniel! Great job!! Very original!</td>', 'WOW! Daniel! Great job!! Very original!', '2004-12-20 14:15:12.000000', NULL, 0),
(1070768, 127082, 4482, '<td valign="top">Manny, Manny, Manny... one day, just one day I''ll head back to South-East Asia and we''ll hook up and have a drink of Mekong Whiskey or a banana milkshake. Then we can play with our D70s!!!!  :-D</td>', 'Manny, Manny, Manny... one day, just one day I''ll head back to South-East Asia and we''ll hook up and have a drink of Mekong Whiskey or a banana milkshake. Then we can play with our D70s!!!!  :-D', '2004-12-20 14:18:36.000000', NULL, 0),
(1070772, 127664, 4482, '<td valign="top">Great mood shot. Love the composition! Well deswerved!</td>', 'Great mood shot. Love the composition! Well deswerved!', '2004-12-20 14:19:40.000000', NULL, 0),
(1070807, 127346, 22459, '<td valign="top">Congratulations Daniel a real graphic and funky image.</td>', 'Congratulations Daniel a real graphic and funky image.', '2004-12-20 14:37:53.000000', NULL, 0),
(1070836, 127664, 30757, '<td valign="top"><br/>Nice shot, depressing !!!!<br/> <br/>Tamas</td>', 'Nice shot, depressing !!!! Tamas', '2004-12-20 14:55:34.000000', NULL, 0),
(1070877, 127664, 20779, '<td valign="top">I was so excited and pleased to see this wonderful work of photography rewarded by a ribbon on DPC. I am so glad my fears were unfounded that it wouldn''t have the "slick, glossy" appeal necessary to get a ribbon. Fine photography with real emotion and impact were instead given applause!</td>', 'I was so excited and pleased to see this wonderful work of photography rewarded by a ribbon on DPC. I am so glad my fears were unfounded that it wouldn''t have the "slick, glossy" appeal necessary to get a ribbon. Fine photography with real emotion and impact were instead given applause!', '2004-12-20 15:26:09.000000', NULL, 0),
(1070892, 127664, 16241, '<td valign="top">congrats, only been here 6 months, good going!<br/></td>', 'congrats, only been here 6 months, good going!', '2004-12-20 15:34:19.000000', NULL, 0),
