(1071014, 127664, 20941, '<td valign="top">Congratulations on your Ribbon. This is a wonderful shot, very happy to see you ribbon with this. Well done!</td>', 'Congratulations on your Ribbon. This is a wonderful shot, very happy to see you ribbon with this. Well done!', '2004-12-20 16:41:39.000000', NULL, 0),
